CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- 0. CLEAN DROP ALL OLD TABLES WITH CASCADE TO PREVENT CONFLICTS
DROP TABLE IF EXISTS audit_logs CASCADE;
DROP TABLE IF EXISTS claim_events CASCADE;
DROP TABLE IF EXISTS refunds CASCADE;
DROP TABLE IF EXISTS payments CASCADE;
DROP TABLE IF EXISTS order_lines CASCADE;
DROP TABLE IF EXISTS orders CASCADE;
DROP TABLE IF EXISTS buyback_prices CASCADE;
DROP TABLE IF EXISTS buyback_cases CASCADE;
DROP TABLE IF EXISTS secondhand_units CASCADE;
DROP TABLE IF EXISTS stock_levels CASCADE;
DROP TABLE IF EXISTS staff_branch_assignments CASCADE;
DROP TABLE IF EXISTS reservations CASCADE;
DROP TABLE IF EXISTS product_reviews CASCADE;
DROP TABLE IF EXISTS product_images CASCADE;
DROP TABLE IF EXISTS product_attributes CASCADE;
DROP TABLE IF EXISTS skus CASCADE;
DROP TABLE IF EXISTS products CASCADE;
DROP TABLE IF EXISTS categories CASCADE;
DROP TABLE IF EXISTS brands CASCADE;
DROP TABLE IF EXISTS product_tags CASCADE;
DROP TABLE IF EXISTS banners CASCADE;
DROP TABLE IF EXISTS site_settings CASCADE;
DROP TABLE IF EXISTS role_permissions CASCADE;
DROP TABLE IF EXISTS permissions CASCADE;
DROP TABLE IF EXISTS roles CASCADE;
DROP TABLE IF EXISTS branches CASCADE;
DROP TABLE IF EXISTS users CASCADE;

CREATE TABLE roles (
    id VARCHAR(50) PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    description TEXT,
    is_system BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

ON CONFLICT (id) DO NOTHING;

CREATE TABLE branches (
    id VARCHAR(50) PRIMARY KEY,
    code VARCHAR(20) UNIQUE,
    name VARCHAR(255) NOT NULL,
    address TEXT NOT NULL,
    city VARCHAR(100) NOT NULL,
    phone VARCHAR(20),
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

ON CONFLICT (id) DO NOTHING;

CREATE TABLE brands (
    id VARCHAR(50) PRIMARY KEY,
    name VARCHAR(100),
    country VARCHAR(50),
    description TEXT
);

CREATE TABLE categories (
    id VARCHAR(50) PRIMARY KEY,
    name VARCHAR(100),
    slug VARCHAR(100),
    parent_id VARCHAR(50),
    description TEXT,
    image_url TEXT,
    tag_subtitle VARCHAR(255),
    sort_order INTEGER,
    is_featured BOOLEAN
);

CREATE TABLE products (
    id UUID PRIMARY KEY,
    brand_id VARCHAR(50),
    category_id VARCHAR(50),
    name VARCHAR(255),
    slug VARCHAR(255),
    description TEXT,
    player_type VARCHAR(100),
    image_url TEXT,
    warranty_months INTEGER,
    is_active BOOLEAN,
    created_at TIMESTAMP WITH TIME ZONE,
    play_style VARCHAR(50),
    play_style_code VARCHAR(30),
    balance_category VARCHAR(50),
    shaft_stiffness VARCHAR(50),
    weight_classes VARCHAR(50),
    grip_sizes VARCHAR(50),
    max_tension_lbs INTEGER,
    max_tension_kg NUMERIC,
    length_mm INTEGER,
    frame_shape VARCHAR(50),
    level VARCHAR(50),
    image_source VARCHAR(255),
    sales_count INTEGER,
    meta_title VARCHAR(255),
    meta_description TEXT,
    sort_order INTEGER,
    tags TEXT[]
);

CREATE TABLE skus (
    id VARCHAR(100) PRIMARY KEY,
    product_id UUID,
    weight VARCHAR(10),
    grip_size VARCHAR(10),
    balance_point_mm INTEGER,
    stiffness VARCHAR(50),
    max_tension_lbs INTEGER,
    price BIGINT,
    is_active BOOLEAN,
    size VARCHAR(50),
    color VARCHAR(50),
    variant_name VARCHAR(100)
);

CREATE TABLE product_images (
    id UUID PRIMARY KEY,
    product_id UUID,
    angle VARCHAR(20),
    image_url TEXT,
    sort_order INTEGER,
    is_primary BOOLEAN,
    created_at TIMESTAMP WITHOUT TIME ZONE
);

CREATE TABLE product_tags (
    id VARCHAR(50) PRIMARY KEY,
    code VARCHAR(50),
    name VARCHAR(100),
    bg_color VARCHAR(50),
    text_color VARCHAR(50),
    icon_name VARCHAR(50),
    is_active BOOLEAN,
    sort_order INTEGER,
    created_at TIMESTAMP WITH TIME ZONE
);

CREATE TABLE banners (
    id VARCHAR(50) PRIMARY KEY,
    badge VARCHAR(100),
    title VARCHAR(255),
    description TEXT,
    primary_cta_text VARCHAR(100),
    primary_cta_link VARCHAR(255),
    secondary_cta_text VARCHAR(100),
    secondary_cta_link VARCHAR(255),
    image_url TEXT,
    product_tag VARCHAR(100),
    product_sub VARCHAR(100),
    product_price VARCHAR(50),
    sort_order INTEGER,
    is_active BOOLEAN,
    created_at TIMESTAMP WITH TIME ZONE,
    features JSONB,
    start_at TIMESTAMP WITH TIME ZONE,
    end_at TIMESTAMP WITH TIME ZONE,
    updated_at TIMESTAMP WITH TIME ZONE,
    created_by VARCHAR(100),
    position VARCHAR(50),
    mobile_image_url TEXT,
    link_url VARCHAR(255)
);

CREATE TABLE site_settings (
    key VARCHAR(100) PRIMARY KEY,
    value TEXT,
    group_name VARCHAR(50),
    description TEXT,
    updated_at TIMESTAMP WITH TIME ZONE,
    updated_by VARCHAR(100)
);

CREATE TABLE secondhand_units (
    id VARCHAR(50) PRIMARY KEY,
    buyback_case_id VARCHAR(50),
    serial_number VARCHAR(100),
    model_name VARCHAR(100),
    grade VARCHAR(10),
    branch_id VARCHAR(50),
    resale_price BIGINT,
    warranty_days INTEGER,
    condition_notes TEXT,
    images_json TEXT,
    status VARCHAR(50),
    approved_by VARCHAR(100),
    approved_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE,
    updated_at TIMESTAMP WITH TIME ZONE,
    version INTEGER
);

CREATE TABLE stock_levels (
    sku VARCHAR(50) NOT NULL,
    branch_id VARCHAR(50) NOT NULL,
    on_hand INT NOT NULL DEFAULT 0,
    reserved INT NOT NULL DEFAULT 0,
    PRIMARY KEY (sku, branch_id)
);

