INSERT INTO banners (id, badge, title, description, primary_cta_text, primary_cta_link, secondary_cta_text, secondary_cta_link, image_url, product_tag, product_sub, product_price, sort_order, is_active, created_at, features, start_at, end_at, updated_at, created_by, position, mobile_image_url, link_url) VALUES ('banner-1-gosen-ryzonic', 'NEW MODEL — MADE IN JAPAN', 'GOSEN RYZONIC 62 — CƯỚC CẦU LÔNG CAO CẤP', 'Dòng cước cao cấp 0.62mm độ nảy tối đa, lực đập bộc phát, âm thanh nổ vang rền và đường cầu kiểm soát sắc nét.', 'Khám phá cước Gosen', '/day-cuoc', 'Căng cước lấy ngay', '/day-cuoc', '/images/banners/banner-1-gosen-ryzonic.png', 'Gosen Ryzonic 62 String', NULL, 'Cước thi đấu BWF', 1, true, '2026-10-16T02:17:57.718Z', '["Sức mạnh bộc phát 10/10","Âm thanh nổ vang rền 9/10","Độ nhám kiểm soát cầu 9.5/10"]'::jsonb, NULL, NULL, '2026-10-16T14:32:40.539Z', NULL, 'HERO_SLIDER', '/images/banners/banner-1-gosen-ryzonic.png', '/day-cuoc') ON CONFLICT DO NOTHING;
INSERT INTO banners (id, badge, title, description, primary_cta_text, primary_cta_link, secondary_cta_text, secondary_cta_link, image_url, product_tag, product_sub, product_price, sort_order, is_active, created_at, features, start_at, end_at, updated_at, created_by, position, mobile_image_url, link_url) VALUES ('banner-2-dam-me-san-cau', 'PLAY BETTER EVERYDAY', 'ĐAM MÊ BẮT ĐẦU TỪ SÂN — VỢT, GIÀY, QUẦN ÁO, PHỤ KIỆN', 'Trang bị thi đấu cầu lông chính hãng toàn diện: Vợt Yonex, giày bám sân cao cấp, bao vợt và phụ kiện chuyên nghiệp.', 'Mua ngay', '/vot-cau-long', 'Hệ thống cửa hàng', '/chi-nhanh', '/images/banners/banner-2-dam-me-san-cau.png', 'Hệ sinh thái Yonex chính hãng', NULL, 'Bộ sưu tập mới', 2, true, '2026-10-16T02:17:57.718Z', '["Hàng chính hãng 100%","Giao hàng nhanh toàn quốc","Tư vấn tận tâm 24/7"]'::jsonb, NULL, NULL, '2026-10-16T02:17:57.718Z', NULL, 'HERO_SLIDER', '/images/banners/banner-2-dam-me-san-cau.png', '/vot-cau-long') ON CONFLICT DO NOTHING;
INSERT INTO banners (id, badge, title, description, primary_cta_text, primary_cta_link, secondary_cta_text, secondary_cta_link, image_url, product_tag, product_sub, product_price, sort_order, is_active, created_at, features, start_at, end_at, updated_at, created_by, position, mobile_image_url, link_url) VALUES ('banner-3-but-pha-san-cau', 'BỘ SƯU TẬP MỚI 2026', 'BỨT PHÁ TRÊN SÂN CẦU — BỘ SƯU TẬP THỂ THAO ĐỈNH CAO', 'Trang phục thi đấu phối màu đỏ đen rực lửa, giày thi đấu trợ lực gót chân, balo chống sốc và vợt tấn công uy lực.', 'Khám phá ngay', '/vot-cau-long', 'Xem quần áo thi đấu', '/quan-ao', '/images/banners/banner-3-but-pha-san-cau.png', 'Bộ sưu tập Bứt Phá Sân Cầu', NULL, 'Sản phẩm mới', 3, true, '2026-10-16T02:17:57.718Z', '["Áo đấu co giãn 4 chiều","Giày đệm chống chấn","Balo đựng vợt cách nhiệt"]'::jsonb, NULL, NULL, '2026-10-16T02:17:57.718Z', NULL, 'HERO_SLIDER', '/images/banners/banner-3-but-pha-san-cau.png', '/vot-cau-long') ON CONFLICT DO NOTHING;
INSERT INTO banners (id, badge, title, description, primary_cta_text, primary_cta_link, secondary_cta_text, secondary_cta_link, image_url, product_tag, product_sub, product_price, sort_order, is_active, created_at, features, start_at, end_at, updated_at, created_by, position, mobile_image_url, link_url) VALUES ('banner-4-rise-smash-repeat', 'BADMINTON PERFORMANCE', 'RISE. SMASH. REPEAT. — BỨT PHÁ GIỚI HẠN CỦA BẠN', 'Vũ khí và trang thiết bị tốc độ cao tông xanh neon điện năng, tối đa hóa lực smash và tốc độ phản xạ liên hoàn trên sân.', 'Khám phá bộ sưu tập', '/vot-cau-long', 'Thử vợt tại quầy', '/chi-nhanh', '/images/banners/banner-4-rise-smash-repeat.png', 'Rise Smash Repeat Collection', NULL, 'Phiên bản thi đấu', 4, true, '2026-10-16T02:17:57.718Z', '["Vợt đầu nhẹ trợ lực phản tạt","Giày đế gai bám sân tuyệt đối","Trang phục thấm hút mồ hôi siêu tốc"]'::jsonb, NULL, NULL, '2026-10-16T02:17:57.718Z', NULL, 'HERO_SLIDER', '/images/banners/banner-4-rise-smash-repeat.png', '/vot-cau-long') ON CONFLICT DO NOTHING;
